import{_ as o,o as e,c as a,a3 as d}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"倍速与时间缩放","description":"","frontmatter":{},"headers":[],"relativePath":"use/timescale.md","filePath":"use/timescale.md","lastUpdated":1791133906000}'),r={name:"use/timescale.md"};function s(l,t,c,i,n,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="倍速与时间缩放" tabindex="-1">倍速与时间缩放 <a class="header-anchor" href="#倍速与时间缩放" aria-label="Permalink to &quot;倍速与时间缩放&quot;">​</a></h1><p><strong>这是全框架最容易让人困惑的一个功能。</strong> 单独用一篇讲清楚。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p><code>sandbox.timeScale</code> 控制<strong>游戏时间的流速</strong>。</p><table tabindex="0"><thead><tr><th>值</th><th>效果</th></tr></thead><tbody><tr><td><code>0</code></td><td><strong>暂停</strong>（所有东西冻结）</td></tr><tr><td><code>0.5</code></td><td>慢放</td></tr><tr><td><code>1.0</code></td><td><strong>原版</strong>（默认）</td></tr><tr><td><code>2.0</code></td><td>快进 2 倍</td></tr><tr><td><code>3.0</code></td><td>快进 3 倍</td></tr></tbody></table><h2 id="它影响什么" tabindex="-1">它影响什么 <a class="header-anchor" href="#它影响什么" aria-label="Permalink to &quot;它影响什么&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">关键：它不只影响「动画」</p><p>时间缩放会同时作用于<strong>所有按时间推进的东西</strong>：</p><ul><li>开火动画、装填动画</li><li>舰船机动</li><li><strong>AI 的行动</strong></li><li>场景转场</li><li>界面补间动画</li></ul><p><strong>所以它不是「播放速度倍速」，而是「整个游戏世界的节奏」。</strong></p></div><h2 id="最常见的困惑" tabindex="-1">最常见的困惑 <a class="header-anchor" href="#最常见的困惑" aria-label="Permalink to &quot;最常见的困惑&quot;">​</a></h2><h3 id="「为什么我点了发射-然后什么都没了」" tabindex="-1">「为什么我点了发射，然后什么都没了」 <a class="header-anchor" href="#「为什么我点了发射-然后什么都没了」" aria-label="Permalink to &quot;「为什么我点了发射，然后什么都没了」&quot;">​</a></h3><p>这是<strong>最常被报告的现象</strong>，而答案是：</p><blockquote><p><strong>你把倍速调得太高了。</strong></p></blockquote><p><strong>发生了什么：</strong></p><p>你按了发射 → 开火动画以 3 倍速播放 → 装填以 3 倍速完成 → AI 以 3 倍速行动 → 转场以 3 倍速播放 → <strong>一瞬间就跳到了下一回合</strong>。</p><p>玩家的感受是「我点了发射，然后游戏就跳过去了」—— 好像什么都没有。</p><h3 id="怎么办" tabindex="-1">怎么办 <a class="header-anchor" href="#怎么办" aria-label="Permalink to &quot;怎么办&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">一句话解决</p><p><strong>点悬浮窗旁边的倍速按钮，把它调回 <code>x1</code>。</strong></p></div><p>那个按钮点一下循环：<code>x1 → x2 → x3 → x1</code>。</p><p>如果当前倍速不是 <code>x1</code>，按钮会显示<strong>警示色</strong>，提醒你现在不是正常速度。</p><h2 id="怎么调倍速" tabindex="-1">怎么调倍速 <a class="header-anchor" href="#怎么调倍速" aria-label="Permalink to &quot;怎么调倍速&quot;">​</a></h2><h3 id="方式一-悬浮窗快捷按钮" tabindex="-1">方式一：悬浮窗快捷按钮 <a class="header-anchor" href="#方式一-悬浮窗快捷按钮" aria-label="Permalink to &quot;方式一：悬浮窗快捷按钮&quot;">​</a></h3><p>悬浮窗旁边的 <code>x1</code> 按钮，点一下循环。</p><p><strong>快捷循环不含暂停档</strong>（<code>x1 → x2 → x3 → x1</code>），这是故意的。</p><h3 id="方式二-参数页滑块" tabindex="-1">方式二：参数页滑块 <a class="header-anchor" href="#方式二-参数页滑块" aria-label="Permalink to &quot;方式二：参数页滑块&quot;">​</a></h3><p>「参数」页 → 沙盒分组 → 拖动 <code>sandbox.timeScale</code> 滑块。</p><p>这里**可以拖到 <code>0</code>（暂停）**和小数（如 <code>0.5</code> 慢放）。</p><h2 id="为什么倍速不保存" tabindex="-1">为什么倍速不保存 <a class="header-anchor" href="#为什么倍速不保存" aria-label="Permalink to &quot;为什么倍速不保存&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这是一个刻意的设计决定</p><p><code>sandbox.timeScale</code> <strong>只在本次运行有效</strong>。</p><p>下次启动游戏，它会<strong>强制回到 <code>1.0</code></strong>。</p></div><p><strong>为什么这么设计？</strong></p><p>假设它被存进了设置文件：</p><ol><li>你某次把倍速调到了 <code>3.0</code></li><li>退出游戏</li><li>过几天再打开</li><li>发现「<strong>整个游戏都快得不正常</strong>」</li><li>但你<strong>完全不记得自己调过倍速</strong></li><li>于是开始怀疑「游戏坏了 / Mod 出问题了」</li></ol><p>这个体验很糟。框架的选择是：</p><blockquote><p><strong>宁可让你每次重新调，也不让你陷入「我不知道自己改过什么」的状态。</strong></p></blockquote><div class="tip custom-block"><p class="custom-block-title">这是「实验性参数不跨会话持久化」原则的应用</p><p>同样的原则适用于所有<strong>危险性高、容易遗忘</strong>的参数。</p><p>参数每次启动回到安全默认值 —— 这是保证「你永远知道游戏处于什么状态」的基础。</p></div><h2 id="为什么暂停档不进快捷循环" tabindex="-1">为什么暂停档不进快捷循环 <a class="header-anchor" href="#为什么暂停档不进快捷循环" aria-label="Permalink to &quot;为什么暂停档不进快捷循环&quot;">​</a></h2><p>快捷循环是 <code>x1 → x2 → x3 → x1</code>，<strong>跳过了 <code>0</code></strong>。</p><p><strong>原因：</strong></p><p>误触到暂停 → <code>Time.timeScale = 0</code> → <strong>所有游戏协程冻结</strong> → 游戏看起来完全死机了。</p><p>玩家的第一反应是「游戏挂了」，然后可能会强退、重装，甚至以为 Mod 搞坏了游戏。</p><p><strong>所以不把暂停放在容易误点到的位置。</strong></p><p>想用暂停，去参数页拖滑块（那里需要明确的操作动作，不容易误触）。</p><h2 id="倍速的合理用法" tabindex="-1">倍速的合理用法 <a class="header-anchor" href="#倍速的合理用法" aria-label="Permalink to &quot;倍速的合理用法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议倍速</th></tr></thead><tbody><tr><td>正常玩</td><td><code>1.0</code>（原版）</td></tr><tr><td>想快速过一遍战斗动画</td><td><code>2.0</code></td></tr><tr><td>想看炮弹出膛的细节</td><td><code>0.5</code></td></tr><tr><td>想暂停下来仔细看局势</td><td><code>0</code>（从参数页拖）</td></tr><tr><td>长距离航行等待</td><td><code>2.0</code> – <code>3.0</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">建议：平时保持 1.0</p><p>倍速主要是「偶尔用一下」的功能。</p><p>如果一直开着倍速玩，会失去很多战斗的细节和紧张感 —— 而且更容易出现「我点了发射但什么都没了」的困惑。</p></div><h2 id="和其他参数的关系" tabindex="-1">和其他参数的关系 <a class="header-anchor" href="#和其他参数的关系" aria-label="Permalink to &quot;和其他参数的关系&quot;">​</a></h2><p>倍速是<strong>唯一一个影响「节奏」而不是「数值」的参数</strong>。</p><table tabindex="0"><thead><tr><th>参数类型</th><th>影响</th></tr></thead><tbody><tr><td>伤害、命中</td><td>打得多疼</td></tr><tr><td>经济、威望</td><td>赚得多快</td></tr><tr><td><strong>时间缩放</strong></td><td><strong>整个世界跑得多快</strong></td></tr><tr><td>AI 反应</td><td>敌人决策快慢（这是 AI 内部节奏，和全局时间是两回事）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>timeScale</code> 和 <code>ai.reactionMul</code> 的区别</p><p>容易混：</p><table tabindex="0"><thead><tr><th>参数</th><th>影响</th></tr></thead><tbody><tr><td><code>sandbox.timeScale</code></td><td><strong>所有</strong>东西的时间流速（包括你自己的动画）</td></tr><tr><td><code>ai.reactionMul</code></td><td>只影响 <strong>AI 决策</strong>的节奏</td></tr></tbody></table><p>想「让敌人反应慢点」→ 调 <code>ai.reactionMul</code>。 想「整个游戏快进」→ 调 <code>sandbox.timeScale</code>。</p></div><h2 id="排查清单" tabindex="-1">排查清单 <a class="header-anchor" href="#排查清单" aria-label="Permalink to &quot;排查清单&quot;">​</a></h2><p>遇到「游戏节奏不对」，按顺序检查：</p><ol><li><strong>倍速是多少</strong> → 状态页会显示当前倍速</li><li><strong>是不是 <code>1.0</code></strong> → 不是就调回 <code>1.0</code></li><li><strong>还是不对</strong> → 看日志页有没有错误</li><li><strong>怀疑参数问题</strong> → 状态页看偏离清单</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>完整沙盒参数 → <a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a></li><li>状态实时查看 → <a href="/AtlanticFleetSite/docs/use/status-page">状态页：看现场</a></li><li>操作技巧 → <a href="/AtlanticFleetSite/docs/use/gestures">悬浮窗操作技巧</a></li></ul>',52)])])}const b=o(r,[["render",s]]);export{g as __pageData,b as default};
